#!/usr/bin/env node
// Facet token build. Zero dependencies: `node scripts/build.mjs`
// Reads tokens/*.json and brand/brand.json and writes css/tokens.css, css/fonts.css, css/typography.css,
// css/materials.css, css/tailwind.css, css/shadcn.css, js/tokens.mjs, the classic-script copies in preview/
// and the single-file onboarding page.
// Never hand-edit the generated files; edit the JSON (or run scripts/brand.mjs) and rebuild.

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { normalize, derive, report, sanitizeSvg, LABELS } from './brand-core.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => JSON.parse(readFileSync(join(root, p), 'utf8'));
const write = (p, s) => {
  mkdirSync(dirname(join(root, p)), { recursive: true });
  writeFileSync(join(root, p), s);
  console.log('wrote', p);
};

const prim = read('tokens/primitives.tokens.json');
const type = read('tokens/typography.tokens.json').typography;
const sem = read('tokens/facet.semantic.json');

const HEADER = `/* GENERATED by scripts/build.mjs. Do not edit by hand. */\n`;
const isTok = (o) => o && typeof o === 'object' && '$value' in o;
const ext = (t) => (t.$extensions && t.$extensions.facet) || {};

// ---------- brand layer ----------
// brand/brand.json holds the project's choices. scripts/brand-core.mjs turns them into token changes, which are
// applied here before anything is written, so every output (CSS, Tailwind bridge, resolved JS values) agrees.
// applyBrand() returns the derived brand; the onboarding page is built from a second pass over the defaults.
function applyBrand(config, prim, sem) {
  const brand = derive(config, prim);
  const tok = (light, dark) => ({ $type: 'color', $value: light, $extensions: { facet: { dark } } });
  const scaleOf = (s) => Object.fromEntries(Object.keys(s.light).map((k) => [k, tok(s.light[k], s.dark[k])]));
  // The accent scale: the default is the violet scale verbatim (wide-gamut values included).
  prim.color.accent = brand.accent.p3 ? JSON.parse(JSON.stringify(brand.accent.p3)) : scaleOf(brand.accent.scale);
  if (brand.grays) {
    prim.color.gray = scaleOf(brand.grays.gray);
    prim.color.background = scaleOf(brand.grays.background);
  }
  for (const [k, v] of Object.entries(brand.shadow)) prim.shadow[k] = { $type: 'shadow', $value: v.light, $extensions: { facet: { dark: v.dark } } };
  for (const [k, v] of Object.entries(brand.radius)) prim.radius[k] = { ...(prim.radius[k] || { $type: 'dimension' }), $value: `${v}px` };
  prim.font.family.sans.$value = brand.font.sans;
  prim.font.family.mono.$value = brand.font.mono;
  for (const [path, v] of Object.entries(brand.semantic)) {
    const [g, k] = path.split('.');
    const t = sem[g][k];
    t.$value = v.value;
    if (v.dark) t.$extensions = { facet: { dark: v.dark } }; else delete t.$extensions;
  }
  return brand;
}
const primBase = JSON.parse(JSON.stringify(prim)); // untouched primitives, for the onboarding page
const semBase = JSON.parse(JSON.stringify(sem));
const brandFile = existsSync(join(root, 'brand/brand.json')) ? read('brand/brand.json') : {};
const checked = normalize(brandFile);
for (const w of checked.warnings) console.warn('brand warning:', w);
if (checked.errors.length) {
  console.error('brand/brand.json is not valid:\n  ' + checked.errors.join('\n  '));
  process.exit(1);
}
const brand = applyBrand(checked.config, prim, sem);
{
  const failing = brand.checks.filter((c) => !c.pass);
  if (failing.length) {
    console.error('The brand config fails contrast:\n  ' + failing.map((c) => `${c.pair} (${c.mode}): ${c.ratio}:1, needs ${c.min}:1`).join('\n  '));
    process.exit(1);
  }
  if (checked.config.logo) {
    const file = join(root, 'brand', checked.config.logo);
    if (!existsSync(file)) { console.error(`brand/brand.json names the logo "${checked.config.logo}", but brand/${checked.config.logo} does not exist.`); process.exit(1); }
    const logo = sanitizeSvg(readFileSync(file, 'utf8'));
    if (!logo.ok) { console.error(`brand/${checked.config.logo}:\n  ` + logo.errors.join('\n  ')); process.exit(1); }
    // A one-color logo also ships in currentColor, so an inlined copy follows the theme.
    if (logo.mono) write('brand/logo.mono.svg', logo.monoSvg + '\n');
  }
}
const MODES = checked.config.modes;

// ---------- semantic aliases ----------
// A semantic token may point at another semantic token ({brand.solid}); CSS keeps the reference live,
// and deref() follows it to the color step for resolved values and the specimen map.
const SEMREF = /^\{(?!color\.)([a-z-]+)\.([a-z0-9-]+)\}$/;
const semAt = (g, k) => sem[g] && sem[g][k];
const deref = (val, mode) => {
  const m = String(val).match(SEMREF);
  if (!m) return val;
  const t = semAt(m[1], m[2]);
  if (!t) throw new Error(`Unknown semantic reference ${val}`);
  return deref(mode === 'dark' ? (ext(t).dark || t.$value) : t.$value, mode);
};
// A value may also mix two references: color-mix(in srgb, {brand.fg} 55%, {color.gray.1000}). CSS keeps the mix
// live; resolved values (js/tokens.mjs) compute it per theme.
const SEMREF_ALL = /\{(?!color\.)([a-z-]+)\.([a-z0-9-]+)\}/g;
const MIX = /^color-mix\(in srgb, (\{[^}]+\}) (\d+)%, (\{[^}]+\})\)$/;
const alias = (v) =>
  String(v).replace(SEMREF_ALL, (_, g, k) => `var(--fc-${g}-${k})`)
    .replace(/\{color\.([a-z-]+)\.(\d+)\}/g, (_, s, n) => `var(--ds-${s}-${n})`);
const hexMix = (a, b, p) => {
  const ch = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
  const [x, y] = [ch(a), ch(b)];
  return '#' + x.map((c, i) => Math.round(c * p + y[i] * (1 - p)).toString(16).padStart(2, '0')).join('');
};
// ---------- tokens.css, as a function of the tokens and the brand ----------
function emitTokens(prim, sem, MODES, brand) {
  // ---------- primitives ----------
  const light = [], dark = [], p3l = [], p3d = [];
  for (const [scale, steps] of Object.entries(prim.color)) {
    for (const [step, t] of Object.entries(steps)) {
      const name = `--ds-${scale}-${step}`;
      light.push(`${name}: ${t.$value};`);
      if (ext(t).dark) dark.push(`${name}: ${ext(t).dark};`);
      if (ext(t).p3) p3l.push(`${name}: ${ext(t).p3};`);
      if (ext(t).p3Dark) p3d.push(`${name}: ${ext(t).p3Dark};`);
    }
  }
  light.push('--ds-white: #fff;', '--ds-black: #000;');
  for (const [k, t] of Object.entries(prim.shadow)) {
    light.push(`--ds-shadow-${k}: ${t.$value};`);
    if (ext(t).dark && ext(t).dark !== t.$value) dark.push(`--ds-shadow-${k}: ${ext(t).dark};`);
  }
  // Focus follows the brand accent: ring and input halo both read --fc-focus-color.
  light.push(
    '--ds-focus-color: var(--fc-focus-color);',
    '--ds-focus-ring: 0 0 0 2px var(--ds-background-100), 0 0 0 4px var(--ds-focus-color);',
    '--ds-focus-ring-outline: 2px solid var(--ds-focus-color);',
    '--ds-focus-border: 0 0 0 1px var(--ds-focus-color), 0px 0px 0px 4px color-mix(in srgb, var(--ds-focus-color) 24%, transparent);',
    '--ds-overlay-backdrop-color: var(--ds-gray-100);',
    '--ds-overlay-backdrop-opacity: .8;'
  );
  dark.push('--ds-focus-border: 0 0 0 1px var(--ds-focus-color), 0px 0px 0px 4px color-mix(in srgb, var(--ds-focus-color) 32%, transparent);', '--ds-overlay-backdrop-color: var(--ds-background-200);');

  // ---------- scalar tokens ----------
  const scalars = [];
  const ff = prim.font.family;
  scalars.push(`--fc-font-sans: ${ff.sans.$value};`, `--fc-font-mono: ${ff.mono.$value};`);
  for (const [k, t] of Object.entries(prim.font.weight)) scalars.push(`--fc-weight-${k}: ${t.$value};`);
  for (const [k, t] of Object.entries(prim.space)) scalars.push(`--fc-space-${k.replace('.', '_')}: ${t.$value};`);
  for (const [k, t] of Object.entries(prim.radius)) scalars.push(`--fc-radius-${k}: ${t.$value};`);
  for (const [k, t] of Object.entries(prim.size.control)) scalars.push(`--fc-control-${k}: ${t.$value};`);
  for (const [k, t] of Object.entries(prim.size.row)) scalars.push(`--fc-row-${k}: ${t.$value};`);
  for (const [k, t] of Object.entries(prim.size.layout || {})) scalars.push(`--fc-${k}: ${t.$value};`);
  scalars.push(`--fc-page-width: ${prim.size.page.$value};`, `--fc-page-margin: ${prim.size['page-margin'].$value};`);
  for (const [k, t] of Object.entries(prim.z)) scalars.push(`--fc-z-${k}: ${t.$value};`);
  for (const [k, v] of Object.entries(brand.scalars)) scalars.push(`--fc-${k}: ${v};`);
  for (const [k, t] of Object.entries(prim.motion.easing)) scalars.push(`--fc-ease-${k}: cubic-bezier(${t.$value.join(', ')});`);
  for (const [k, t] of Object.entries(prim.motion.duration)) scalars.push(`--fc-duration-${k}: ${t.$value};`);

  const semLight = [], semDark = [];
  (function walk(node, path) {
    for (const [k, v] of Object.entries(node)) {
      if (k.startsWith('$')) continue;
      const p = [...path, k];
      if (isTok(v)) {
        const name = `--fc-${p.join('-')}`;
        semLight.push(`${name}: ${alias(v.$value)};`);
        if (ext(v).dark) semDark.push(`${name}: ${alias(ext(v).dark)};`);
      } else if (v && typeof v === 'object') walk(v, p);
    }
  })(sem, []);

  // ---------- nested-theme safety ----------
  // Custom properties resolve var() where they are declared, so a dark scope nested inside a light
  // page must re-declare every alias that points at a themed primitive. Merge them in.
  const keyOf = (l) => l.slice(0, l.indexOf(':'));
  const merge = (base, over) => {
    const m = new Map(base.filter((l) => l.includes('var(')).map((l) => [keyOf(l), l]));
    for (const l of over) m.set(keyOf(l), l);
    return [...m.values()];
  };
  const darkAll = merge([...light, ...semLight], [...dark, ...semDark]);

  // ---------- tokens.css ----------
  // Modes (brand/brand.json "modes"): both follows the OS, light never goes dark by itself, dark is dark unless a
  // scope forces light. A forced scope (class or data-theme) works in every mode, so one dark panel is always possible.
  const block = (sel, lines) => `${sel} {\n  ${lines.join('\n  ')}\n}\n`;
  const DARK_SEL = '.dark-theme, [data-theme="dark"]';
  const AUTO_DARK_SEL = ':root:not(.light-theme):not([data-theme="light"])';
  const MODE_NOTE = {
    both: 'Theme: light by default, follows the OS, and can be forced',
    light: 'Theme: light only. The OS preference is ignored; a scope can still be forced',
    dark: 'Theme: dark only. The OS preference is ignored; a scope can still be forced',
  }[MODES];
  const autoDark = (lines) => MODES === 'both'
    ? `@media (prefers-color-scheme: dark) {\n` + block(AUTO_DARK_SEL, lines).replace(/^/gm, '  ') + `}\n`
    : MODES === 'dark' ? block(AUTO_DARK_SEL, lines) : '';
  const tokensCss =
    HEADER +
    `/* Facet tokens. Layer 1: Facet primitives (--ds-*), captured from the vercel.com reference, plus the accent
   scale and any gray, shadow or radius changes from brand/brand.json. Layer 2: Facet semantics (--fc-*).
   ${MODE_NOTE} with class="dark-theme" | "light-theme" or data-theme="dark" | "light"
   on <html> or any subtree. */\n\n` +
    block(':root, .light-theme, [data-theme="light"]', ['color-scheme: light;', ...light, ...scalars, ...semLight]) +
    '\n' + block(DARK_SEL, ['color-scheme: dark;', ...darkAll]) +
    (MODES === 'light' ? '' : '\n' + autoDark(['color-scheme: dark;', ...darkAll])) +
    `\n/* Wide-gamut (Display P3) upgrades, same as the reference. Grays and a custom accent need none. */\n` +
    `@media (color-gamut: p3) {\n  @supports (color: oklch(0 0 0)) {\n` +
    block(':root, .light-theme, [data-theme="light"]', p3l).replace(/^/gm, '    ') +
    block(DARK_SEL, p3d).replace(/^/gm, '    ') +
    (MODES === 'dark' ? block(AUTO_DARK_SEL, p3d).replace(/^/gm, '    ') : '') +
    `  }\n}\n` +
    (MODES === 'both'
      ? `@media (color-gamut: p3) and (prefers-color-scheme: dark) {\n  @supports (color: oklch(0 0 0)) {\n` +
        block(AUTO_DARK_SEL, p3d).replace(/^/gm, '    ') + `  }\n}\n`
      : '');
  return { tokensCss, semLight };
}
const block = (sel, lines) => `${sel} {\n  ${lines.join('\n  ')}\n}\n`;
const { tokensCss, semLight } = emitTokens(prim, sem, MODES, brand);
write('css/tokens.css', tokensCss);

// ---------- fonts.css ----------
// Only the vendored family ships @font-face rules. Other families are loaded by the app (see brand/README.md).
const FONT_FACES = (sans, mono) => `@font-face {
  font-family: "Geist";
  src: url("${sans}") format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Geist Mono";
  src: url("${mono}") format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
`;
write('css/fonts.css', HEADER + (brand.font.vendored
  ? `/* Facet Sans + Mono (the open-source Geist typeface), variable (100 to 900). SIL OFL 1.1, see fonts/OFL-LICENSE.txt.
   In Next.js prefer the \`geist\` package (next/font) and skip this file; both paths expose the same family names. */\n` +
    FONT_FACES('../fonts/Geist-Variable.woff2', '../fonts/GeistMono-Variable.woff2')
  : `/* Type family: ${LABELS.type[checked.config.type]}. ${brand.font.load} */\n`));

// ---------- typography.css ----------
const resolveFam = (v) => (v.includes('mono') ? 'var(--fc-font-mono)' : 'var(--fc-font-sans)');
let typo = HEADER + `/* Facet type roles. Each class sets size, line-height, weight and tracking together.
   Nest <strong> for the Strong (copy/label) or Subtle (heading) modifier. */\n\n`;
const twUtil = [];
for (const [name, t] of Object.entries(type)) {
  const v = t.$value;
  const body = [
    `font-family: ${resolveFam(v.fontFamily)};`,
    `font-size: ${v.fontSize};`,
    `line-height: ${v.lineHeight};`,
    `font-weight: ${v.fontWeight};`,
    `letter-spacing: ${v.letterSpacing};`,
  ];
  typo += block(`.text-${name}`, body);
  twUtil.push(`@utility text-${name} {\n  ${body.join('\n  ')}\n}`);
  const s = ext(t).strong;
  if (s) {
    const sb = [`font-weight: ${s.fontWeight};`];
    if (s.color) sb.push(`color: ${s.color};`);
    typo += block(`.text-${name} > strong`, sb);
  }
}
typo += `\n/* Numeric helpers. Tabular figures for any column, KPI or value that is compared. */\n` +
  block('.tabular, .fc-num', ['font-variant-numeric: tabular-nums;', 'font-feature-settings: "tnum" 1;']) +
  block('.slashed-zero', ['font-variant-numeric: tabular-nums slashed-zero;']) +
  block('.fc-mono', ['font-family: var(--fc-font-mono);']);
write('css/typography.css', typo);

// ---------- materials.css (exact presets) ----------
const mats = {
  base: ['border', 'var(--fc-radius-card)'], small: ['border-small', 'var(--fc-radius-card)'], medium: ['border-medium', 'var(--fc-radius-lg)'], large: ['border-large', 'var(--fc-radius-lg)'],
  tooltip: ['tooltip', 'var(--fc-radius-sm)'], menu: ['menu', 'var(--fc-radius-lg)'], modal: ['modal', 'var(--fc-radius-lg)'], fullscreen: ['fullscreen', 'var(--fc-radius-xl)'],
};
let matCss = HEADER + `/* Facet materials: surface (on the page) and floating (above the page). */\n\n`;
for (const [k, [sh, r]] of Object.entries(mats)) {
  matCss += block(`.material-${k}`, ['background-color: var(--ds-background-100);', `box-shadow: var(--ds-shadow-${sh});`, `border-radius: ${r};`]);
}
write('css/materials.css', matCss);

// ---------- tailwind.css (Tailwind v4 theme bridge) ----------
const twColors = [];
for (const [scale, steps] of Object.entries(prim.color)) {
  // Hue allocation (DESIGN.md): the accent is reached only through its semantic utilities (fc-brand-*,
  // fc-highlight-*), and purple has no job, so neither gets bg-* / text-* utilities.
  if (scale === 'purple' || scale === 'accent') continue;
  for (const step of Object.keys(steps)) twColors.push(`--color-${scale}-${step}: var(--ds-${scale}-${step});`);
}
const tw = HEADER + `/* Tailwind CSS v4 bridge. Usage in an app's global CSS:
     @import "tailwindcss";
     @import "facet-kit/css/tailwind.css";
   Tailwind's default palette is removed so only Facet steps exist (bg-gray-100, text-gray-900,
   border-gray-400, bg-background-100, text-blue-900 ...), which mirrors how vercel.com itself
   writes classes. Use a relative path instead of "facet-kit" when the kit is not installed as a package. */\n
@import "./tokens.css";
@import "./materials.css";

@theme inline {
  --color-*: initial;
  --color-white: var(--ds-white);
  --color-black: var(--ds-black);
  --color-transparent: transparent;
  --color-current: currentColor;
  ${twColors.join('\n  ')}
  --font-sans: var(--fc-font-sans);
  --font-mono: var(--fc-font-mono);
  --radius-xs: var(--fc-radius-xs);
  --radius-sm: var(--fc-radius-sm);
  --radius-md: var(--fc-radius-md);
  --radius-lg: var(--fc-radius-lg);
  --radius-xl: var(--fc-radius-xl);
  --shadow-border: var(--ds-shadow-border);
  --shadow-border-small: var(--ds-shadow-border-small);
  --shadow-border-medium: var(--ds-shadow-border-medium);
  --shadow-border-large: var(--ds-shadow-border-large);
  --shadow-tooltip: var(--ds-shadow-tooltip);
  --shadow-menu: var(--ds-shadow-menu);
  --shadow-modal: var(--ds-shadow-modal);
  --shadow-fullscreen: var(--ds-shadow-fullscreen);
  --ease-swift: var(--fc-ease-swift);
}

/* Semantic Facet colors as utilities: bg-fc-surface-subtle, text-fc-signal-go-fg ... */
@theme inline {
  ${semLight.map((l) => l.replace(/^--fc-([^:]+):.*$/, '--color-fc-$1: var(--fc-$1);')).filter((l) => l.startsWith('--color-fc-text') || l.startsWith('--color-fc-surface') || l.startsWith('--color-fc-border') || l.startsWith('--color-fc-status') || l.startsWith('--color-fc-signal') || l.startsWith('--color-fc-delta') || l.startsWith('--color-fc-highlight') || l.startsWith('--color-fc-brand') || l.startsWith('--color-fc-freshness') || l.startsWith('--color-fc-chart')).join('\n  ')}
}

/* dark: fires for a forced dark theme and for the OS preference, matching tokens.css. */
@custom-variant dark {
  &:where(.dark-theme, .dark-theme *, [data-theme="dark"], [data-theme="dark"] *) { @slot; }
  @media (prefers-color-scheme: dark) {
    &:where(:root:not(.light-theme):not([data-theme="light"]), :root:not(.light-theme):not([data-theme="light"]) *) { @slot; }
  }
}

${twUtil.join('\n')}

@utility tabular {
  font-variant-numeric: tabular-nums;
}
`;
write('css/tailwind.css', tw);

// ---------- js/tokens.mjs (resolved values for canvas/SVG charts) ----------
const resolved = { light: {}, dark: {} };
for (const [scale, steps] of Object.entries(prim.color)) {
  for (const [step, t] of Object.entries(steps)) {
    resolved.light[`${scale}-${step}`] = t.$value;
    resolved.dark[`${scale}-${step}`] = ext(t).dark || t.$value;
  }
}
const semResolved = { light: {}, dark: {} };
(function walk(node, path) {
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith('$')) continue;
    const p = [...path, k];
    if (isTok(v)) {
      const key = p.join('-');
      const pick = (val, mode) => String(val).replace(/\{color\.([a-z-]+)\.(\d+)\}/, (_, s, n) => resolved[mode][`${s}-${n}`]);
      const solve = (val, mode) => {
        const m = String(val).match(MIX);
        return m ? hexMix(pick(deref(m[1], mode), mode), pick(deref(m[3], mode), mode), Number(m[2]) / 100) : pick(deref(val, mode), mode);
      };
      semResolved.light[key] = solve(v.$value, 'light');
      semResolved.dark[key] = solve(ext(v).dark || v.$value, 'dark');
    } else if (v && typeof v === 'object') walk(v, p);
  }
})(sem, []);
const js = `// GENERATED by scripts/build.mjs. Do not edit by hand.
// Resolved sRGB values for places CSS variables cannot reach (canvas charts, OG images, emails).
// In the DOM prefer var(--fc-*) / var(--ds-*), which also pick up P3 and theme changes.
export const primitives = ${JSON.stringify(resolved, null, 2)};
export const semantic = ${JSON.stringify(semResolved, null, 2)};
export const typography = ${JSON.stringify(Object.fromEntries(Object.entries(type).map(([k, t]) => [k, t.$value])), null, 2)};
export function token(name, mode = 'light') {
  return semantic[mode][name] ?? primitives[mode][name];
}
`;
write('js/tokens.mjs', js);

// ---------- preview/semantic-map.js (lets the specimen draw which semantic token uses which step) ----------
const aliasMap = { light: {}, dark: {}, desc: {}, groups: {} };
(function walk(node, path) {
  if (path.length && node.$description) aliasMap.groups[path.join('-')] = node.$description;
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith('$')) continue;
    const p = [...path, k];
    if (isTok(v)) {
      if (v.$description) aliasMap.desc[p.join('-')] = v.$description;
      const ref = (x) => { const m = String(x).match(/\{color\.([a-z-]+)\.(\d+)\}/); return m ? `${m[1]}-${m[2]}` : null; };
      aliasMap.light[p.join('-')] = ref(deref(v.$value, 'light'));
      aliasMap.dark[p.join('-')] = ref(deref(ext(v).dark || v.$value, 'dark'));
    } else if (v && typeof v === 'object') walk(v, p);
  }
})(sem, []);
write('preview/semantic-map.js', `// GENERATED by scripts/build.mjs. Do not edit by hand.\nwindow.FACET_ALIASES = ${JSON.stringify(aliasMap)};\n`);

// ---------- css/shadcn.css (shadcn/ui bridge: shadcn supplies behavior, Facet supplies every value) ----------
const SHADCN = {
  background: 'surface-canvas', foreground: 'text-primary',
  card: 'surface-canvas', 'card-foreground': 'text-primary',
  popover: 'surface-canvas', 'popover-foreground': 'text-primary',
  primary: 'surface-contrast', 'primary-foreground': 'text-inverse',
  secondary: 'surface-fill', 'secondary-foreground': 'text-primary',
  muted: 'surface-fill', 'muted-foreground': 'text-secondary',
  accent: 'surface-fill', 'accent-foreground': 'text-primary',
  destructive: 'action-destructive', 'destructive-foreground': null,
  border: 'border-default', input: 'border-alpha', ring: 'focus-color',
  'chart-1': 'chart-1', 'chart-2': 'chart-2', 'chart-3': 'chart-3', 'chart-4': 'chart-4', 'chart-5': 'chart-5',
  sidebar: 'surface-subtle', 'sidebar-foreground': 'text-primary',
  'sidebar-primary': 'surface-contrast', 'sidebar-primary-foreground': 'text-inverse',
  'sidebar-accent': 'surface-fill', 'sidebar-accent-foreground': 'text-primary',
  'sidebar-border': 'border-default', 'sidebar-ring': 'focus-color',
};
const shadVal = (k, v) => (v ? `var(--fc-${v})` : 'var(--ds-white)');
const shadcn = HEADER + `/* shadcn/ui bridge. Components copied from shadcn/ui (Tailwind v4 variable format) render with
   Facet values. Import after tailwind.css:
     @import "tailwindcss";
     @import "facet-kit/css/tailwind.css";
     @import "facet-kit/css/shadcn.css";
   Then delete the :root, .dark and @theme inline blocks that shadcn init writes, and keep
   "cssVariables": true in components.json. The Tailwind v3 format (hsl(var(--x))) cannot be bridged.
   Only the focus ring maps to the accent; highlights stay reachable only through --fc-highlight-*. Radius stays Facet's own
   rounded-* scale; --radius exists only for components that read it directly. */

:root, .light-theme, [data-theme="light"], .dark-theme, [data-theme="dark"] {
  ${Object.entries(SHADCN).map(([k, v]) => `--${k}: ${shadVal(k, v)};`).join('\n  ')}
  --radius: var(--fc-radius-sm);
}

@theme inline {
  ${Object.keys(SHADCN).map((k) => `--color-${k}: var(--${k});`).join('\n  ')}
}
`;
write('css/shadcn.css', shadcn);

// ---------- preview/field.js (classic-script copy of js/field.mjs for file:// previews and artifacts) ----------
{
  const src = readFileSync(join(root, 'js/field.mjs'), 'utf8').replace(/^export /gm, '');
  write('preview/field.js', `// GENERATED from js/field.mjs by scripts/build.mjs. Do not edit by hand.\n(function () {\n${src}\nwindow.FacetField = { mountField, autoMount };\n})();\n`);
}
{
  const src = readFileSync(join(root, 'js/tips.mjs'), 'utf8').replace(/^export /gm, '');
  write('preview/tips.js', `// GENERATED from js/tips.mjs by scripts/build.mjs. Do not edit by hand.\n(function () {\n${src}\nwindow.FacetTips = { mountTips };\n})();\n`);
}
{
  const dots = readFileSync(join(root, 'js/dots.mjs'), 'utf8').replace(/^export /gm, '');
  write('preview/dots.js', `// GENERATED from js/dots.mjs by scripts/build.mjs. Do not edit by hand.\n(function () {\n${dots}\nwindow.FacetDots = { createStage, reducedMotion, alloc };\n})();\n`);
  const undo = readFileSync(join(root, 'js/undo.mjs'), 'utf8').replace(/^export /gm, '');
  write('preview/undo.js', `// GENERATED from js/undo.mjs by scripts/build.mjs. Do not edit by hand.\n(function () {\n${undo}\nwindow.FacetUndo = { mountUndo };\n})();\n`);
}
{
  const src = readFileSync(join(root, 'js/time.mjs'), 'utf8').replace(/^export /gm, '');
  const forms = readFileSync(join(root, 'js/forms.mjs'), 'utf8').replace(/^export /gm, '');
  write('preview/forms.js', `// GENERATED from js/forms.mjs by scripts/build.mjs. Do not edit by hand.\n(function () {\n${forms}\nwindow.FacetForms = { bindOptionHelpers, bindSliders, sliderShare };\n})();\n`);
  write('preview/time.js', `// GENERATED from js/time.mjs by scripts/build.mjs. Do not edit by hand.\n(function () {\n${src}\nwindow.FacetTime = { formatDuration, formatAgo, formatUntil, formatRelative, stampTimes };\n})();\n`);
}

// ---------- onboarding/index.html (one self-contained file: opens from disk, as an attachment or as a hosted page) ----------
{
  const srcPath = join(root, 'onboarding/onboarding.src.html');
  if (existsSync(srcPath)) {
    const text = (p) => readFileSync(join(root, p), 'utf8');
    const b64 = (p) => 'data:font/woff2;base64,' + readFileSync(join(root, p)).toString('base64');
    // Always drawn from the default brand, so the page previews each choice against the untouched system.
    const defaults = normalize({}).config;
    const primDefault = JSON.parse(JSON.stringify(primBase)), semDefault = JSON.parse(JSON.stringify(semBase));
    const defaultTokens = emitTokens(primDefault, semDefault, 'both', applyBrand(defaults, primDefault, semDefault)).tokensCss;
    const layers = ['base', 'typography', 'materials', 'components', 'data', 'charts', 'lists', 'forms', 'shell', 'settings', 'surfaces', 'flows'];
    const core = text('scripts/brand-core.mjs').replace(/^export /gm, '');
    const base = { color: Object.fromEntries(['gray', 'background', 'purple', 'blue', 'red', 'amber', 'green'].map((k) => [k, primBase.color[k]])), shadow: primBase.shadow };
    const page = text('onboarding/onboarding.src.html')
      .replace('/*__FACET_CSS__*/', () => [defaultTokens, FONT_FACES(b64('fonts/Geist-Variable.woff2'), b64('fonts/GeistMono-Variable.woff2')), ...layers.map((l) => text(`css/${l}.css`))].join('\n'))
      .replace('/*__BRAND_CORE__*/', () => core)
      .replace('/*__BASE__*/', () => JSON.stringify(base))
      .replace('/*__CURRENT__*/', () => JSON.stringify(checked.config));
    write('onboarding/index.html', page);
  }
}

